def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(out), len(out[0])
    points = {}
    for r in range(h):
        for c in range(w):
            if out[r][c]:
                points[out[r][c]] = (r, c)

    if 1 in points:
        r, c = points[1]
        for j in range(c + 1, c + 3):
            if 0 <= j < w:
                out[r][j] = 5
        if 0 <= r - 1 < h and 0 <= c + 2 < w:
            out[r - 1][c + 2] = 1

    if 2 in points:
        r, c = points[2]
        for j in range(c - 4, c):
            if 0 <= j < w:
                out[r][j] = 5
        if 0 <= c - 4 < w:
            out[r][c - 4] = 2

    verticals = []
    for value, dr in ((3, 3), (6, -6)):
        if value in points:
            r, c = points[value]
            end_r = r + dr
            step = 1 if dr > 0 else -1
            for rr in range(r + step, end_r, step):
                if 0 <= rr < h:
                    out[rr][c] = 5
            if 0 <= end_r < h:
                out[end_r][c] = value
            verticals.append((r, c, end_r))

    if 2 in points:
        hr, hc = points[2]
        for vr, vc, end_r in verticals:
            if hc - 4 <= vc <= hc and min(vr, end_r) <= hr <= max(vr, end_r):
                out[hr][vc] = 4
                rr, cc = hr + 1, vc - 1
                while rr < h and cc >= 0:
                    out[rr][cc] = 4
                    rr += 1
                    cc -= 1
    return out
